SELECT V1.CODGERALOPER, COUNT(DISTINCT V2.SEQPRODUTO) AS SKUS, SUM(V2.VLRITEM + NVL(V2.VLRICMSST, 0) + NVL(V2.VLRIPI, 0)) AS VALOR FROM MLFV_BASENFE V1 JOIN MFLV_BASEDFITEM V2 ON V2.NROEMPRESA = V1.NROEMPRESA AND V2.SEQNF = V1.SEQNF AND V2.TIPNOTAFISCAL = V1.TIPNOTAFISCAL AND V2.SERIEDF = V1.SERIENF AND V2.NUMERODF = V1.NUMERONF AND V2.SEQPESSOA = V1.SEQPESSOA INNER JOIN MAP_PRODUTO PX ON PX.SEQPRODUTO = V2.SEQPRODUTO LEFT JOIN MAP_FAMFORNEC FPX ON FPX.SEQFAMILIA = PX.SEQFAMILIA AND FPX.PRINCIPAL = 'S' WHERE V1.TIPNOTAFISCAL = 'S' AND NVL(V1.STATUSNF, 'A') != 'C' AND V1.DTAEMISSAO >= TO_DATE('01/05/2026', 'DD/MM/YYYY') AND V1.DTAEMISSAO < TO_DATE('02/05/2026', 'DD/MM/YYYY') + 1 AND FPX.SEQFORNECEDOR = 16491 GROUP BY V1.CODGERALOPER
